sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_completion;
uniform float amzp_inOut;
uniform float amzp_animMode;
uniform float amzp_orderMode;
uniform float amzp_slices;
uniform float amzp_sliceAng;
uniform float amzp_angRand;
uniform float amzp_stagger;
uniform float amzp_feather;
uniform float amzp_tiles;
uniform float amzp_tileOff;
uniform float amzp_blurAmt;
uniform float amzp_fadeCurve;
uniform float amzp_fadeK;
uniform float amzp_zoomDrift;
uniform float amzp_shiftAmt;
uniform float amzp_seed;
uniform float amzp_advScale;
uniform float amzp_advAngle;
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_quality;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float4 layerClamp(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float th1(float x) { x = clamp(x, -15.0, 15.0); float e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float3 th3(float3 x) { x = clamp(x, -15.0, 15.0); float3 e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float4 th4(float4 x) { x = clamp(x, -15.0, 15.0); float4 e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float2x2 rot2(float a) { float c = cos(a), s = sin(a); return float2x2(c, -s, s, c); }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_aSpeed * 0.5) : p; }
    float2 advFC() {
        float2 W = layer;
        float2 q = amzLayerNorm() * W - 0.5 * W;
        q = advRot(q, radians(amzp_advAngle)) / max(amzp_advScale, 0.01);
        return q + 0.5 * W;
    }
    float2 toL(float2 I) {
        float2 W = layer;
        float2 q = advRot((I - 0.5 * W) * max(amzp_advScale, 0.01), -radians(amzp_advAngle));
        return (q + 0.5 * W) / W;
    }
    float2 toP(float2 uv) { float2 W = layer; return (advRot((uv - 0.5) * W, radians(amzp_advAngle)) / max(amzp_advScale, 0.01)) / W + 0.5; }
    float2 fromP(float2 pu) { float2 W = layer; return advRot((pu - 0.5) * W * max(amzp_advScale, 0.01), -radians(amzp_advAngle)) / W + 0.5; }
    float rnd(float2 st) { return fract(sin(dot(st, float2(12.9898, 78.233))) * 43758.5453123); }
    float remap(float r, float mn) { return mix(mn, 1.0, r); }
    float2 rotD(float2 p, float a) { float r = radians(a); float s = sin(r), c = cos(r); return float2x2(c, -s, s, c) * p; }
    float mrep(float x) { float t = fract(x * 0.5) * 2.0; return 1.0 - abs(t - 1.0); }
    float2 applyTiles(float2 uv) {
        if (int(amzp_tiles) == 1) return mix(float2(amzp_tileOff), float2(1.0 - amzp_tileOff), fract(uv));
        if (int(amzp_tiles) == 2) return mix(float2(amzp_tileOff), float2(1.0 - amzp_tileOff), float2(mrep(uv.x), mrep(uv.y)));
        return uv;
    }
    float4 clipAt(int k, float2 puv) {
        bool isLayer = (int(amzp_inOut) == 0) ? (k == 0) : (k == 1);
        if (!isLayer) return float4(0.0);
        float2 u = applyTiles(puv);
        return layerAt(fromP(u));
    }
    float gw(float d, float s) { return exp(-(d * d) / (2.0 * s * s)); }
    float4 blurS(int k, float2 uv, float radius) {
        if (radius <= 0.0001) return clipAt(k, uv);
        float sg = radius * 0.5;
        float4 sum = clipAt(k, uv);
        float tw = 1.0;
        float NR = clamp(floor(amzp_quality + 0.5), 1.0, 5.0);
        for (int ring = 1; ring <= 5; ring++) {
            if (float(ring) > NR) break;
            float rr = radius * float(ring) / NR;
            float w = gw(rr, sg);
            for (int i = 0; i < 10; i++) {
                float an = float(i) / 10.0 * 6.2831853;
                sum += clipAt(k, uv + float2(cos(an), sin(an)) * rr) * w;
                tw += w;
            }
        }
        return sum / tw;
    }
    float progId(float id, float cnt, float sd) {
        if (int(amzp_orderMode) == 0) return remap((id + 1.0) / cnt, amzp_stagger);
        if (int(amzp_orderMode) == 1) return remap((cnt - id) / cnt, amzp_stagger);
        float ci = (cnt - 1.0) * 0.5;
        float dc = abs(id - ci);
        if (int(amzp_orderMode) == 3) return remap((ci - dc + 1.0) / (ci + 1.0), amzp_stagger);
        if (int(amzp_orderMode) == 4) return remap((dc + 1.0) / (ci + 1.0), amzp_stagger);
        return remap(rnd(float2(id) + sd), amzp_stagger);
    }
    float2 sliceData(float2 p, float cnt, float ang, float sd) {
        float2 pr = rotD(p - 0.5, ang) + 0.5;
        float rx = clamp(pr.x * cnt, 0.0, cnt - 0.0001);
        float id = floor(rx), lx = fract(rx);
        float r = progId(id, cnt, sd);
        if (amzp_feather > 0.0) {
            if (lx < amzp_feather) r = mix(progId(clamp(id - 1.0, 0.0, cnt - 1.0), cnt, sd), r, smoothstep(0.0, amzp_feather, lx));
            else if (lx > 1.0 - amzp_feather) r = mix(progId(clamp(id + 1.0, 0.0, cnt - 1.0), cnt, sd), r, smoothstep(1.0, 1.0 - amzp_feather, lx));
        }
        return float2(r, id);
    }
    float2 clampByAngle(float2 o, float a) {
        a = mod(a, 360.0);
        float2 r = o;
        if (a < 90.0) { r.x = clamp(r.x, 0.0, 1.0); r.y = clamp(r.y, -1.0, 0.0); }
        else if (a < 180.0) { r.x = clamp(r.x, 0.0, 1.0); r.y = clamp(r.y, 0.0, 1.0); }
        else if (a < 270.0) { r.x = clamp(r.x, -1.0, 0.0); r.y = clamp(r.y, 0.0, 1.0); }
        else { r.x = clamp(r.x, -1.0, 0.0); r.y = clamp(r.y, -1.0, 0.0); }
        return r;
    }
    void nmMain() {
        float2 W = layer;
        float4 orig = layerAt(amzLayerNorm());
        float2 uv = toP(amzLayerNorm());
        float raw = prog(amzp_completion);
        float progress = (amzp_autop>0.5) ? fract(raw) : clamp(raw, 0.0, 1.0);
        float sd = (amzp_autop>0.5) ? amzp_seed + floor(raw) : amzp_seed;
        float sAng = amzp_sliceAng + amzp_angRand * rnd(float2(sd, sd));
        float cnt = max(floor(amzp_slices + 0.5), 1.0);
        float2 data = sliceData(uv, cnt, sAng, sd);
        progress = smoothstep(0.0, data.x, progress);
        float2 dir = normalize(rotD(float2(1.0), -45.0 - sAng));
        float r0 = smoothstep(0.0, 1.0, progress) * amzp_blurAmt;
        float r1 = smoothstep(0.0, 1.0, 1.0 - progress) * amzp_blurAmt;
        float oA = 1.0 - progress, iA = progress;
        if ((amzp_fadeCurve>0.5)) { float s = clamp(amzp_fadeK, 0.0, 1.0); oA = pow(oA, 1.0 + s * 3.0); iA = pow(iA, 1.0 + s * 3.0); }
        float4 color;
        if (int(amzp_animMode) == 1) {
            float2 c0 = float2(0.5) - dir * amzp_zoomDrift;
            float2 c1 = float2(0.5) + dir * amzp_zoomDrift;
            float s0 = mix(1.0, 0.0, progress);
            float2 uv0 = c0 + (uv - c0) / max(s0, 0.001);
            float s1 = mix(5.0, 1.0, progress);
            float2 uv1 = c1 + (uv - c1) / s1;
            color = blurS(0, uv0, r0) * oA;
            if (int(amzp_tiles) != 0 || (uv1.x >= 0.0 && uv1.x <= 1.0 && uv1.y >= 0.0 && uv1.y <= 1.0)) {
                float4 cn = blurS(1, uv1, r1) * clamp(iA, 0.0, 1.0);
                color = mix(color, cn, progress);
            }
        } else {
            float2 o = float2(1.0 - progress);
            float2 o2 = -float2(1.0) + o;
            o = rotD(o, -45.0 - sAng) * amzp_shiftAmt;
            o2 = (rotD(o2, -45.0 - sAng) + dir * 0.398) * amzp_shiftAmt;
            o2 = clampByAngle(o2, sAng);
            float2 uv0 = uv + o2 * (0.3 + amzp_feather * 0.1);
            float2 uv1 = uv0 + o - o2 * (0.3 + amzp_feather * 0.1);
            color = blurS(0, uv0, r0) * oA;
            if (int(amzp_tiles) != 0 || (uv1.x >= 0.0 && uv1.x <= 1.0 && uv1.y >= 0.0 && uv1.y <= 1.0)) {
                color = blurS(1, uv1, r1) * clamp(iA, 0.3, 1.0);
            }
        }
        if (raw <= 0.0 && !(amzp_autop>0.5)) color = int(amzp_inOut) == 0 ? layerAt(amzLayerNorm()) : float4(0.0);
        float4 R = color;
        amzOutput = R;
    }
    void amzRender() {
        nmMain();
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
